def single_number(nums):
    counts = {}
    for num in nums:
        counts[num] = counts.get(num, 0) + 1                    # tally every value's frequency
    for value, count in counts.items():
        if count == 1:
            return value
    return -1


if __name__ == "__main__":
    print(single_number([2, 2, 3, 2]))

