def single_number(nums):
    answer = 0
    for bit in range(32):
        count = 0
        for num in nums:
            if (num >> bit) & 1:
                count += 1                                            # how many numbers have this bit set
        if count % 3 == 1:
            answer |= (1 << bit)                                        # the single value has this bit set
    if answer >= 2**31:                                                  # convert back to a signed 32 bit value
        answer -= 2**32
    return answer


if __name__ == "__main__":
    print(single_number([0, 1, 0, 1, 0, 1, 99]))

