def single_number(nums):
    ones, twos = 0, 0
    for num in nums:
        ones = (ones ^ num) & ~twos                              # update which bits have been seen exactly once
        twos = (twos ^ num) & ~ones                                # update which bits have been seen exactly twice
    return ones


if __name__ == "__main__":
    print(single_number([2, 2, 3, 2]))

